/* Procedural animation assets: every clip is generated from a saved seed.
   Teaching labels follow the supplied instructions, not a regulation validator. */
const PING_DURATION=3600;
function isPing(type){return type==='pingpong'||type==='receiver'}
const PING_TYPES=['height','palm','angle','position','occlusion','doubles','sequence','out'];
TASKS.pingpong={name:'乒乓球发球判定',label:'乒乓球发球',icon:'◒',desc:'请观察发球动画，判断本次发球是否违规。F：违规；J：合规。'};
let pingN=20;
function validatePingCount(){const n=Number($('#pingCount').value),valid=Number.isInteger(n)&&n>=20&&n<=100;$('#pingCountError').textContent=valid?'':'请输入20到100之间的整数。';if(valid)pingN=n;return valid}
$('#pingCount').oninput=validatePingCount;
$('#pingOpen').onclick=()=>{if(validatePingCount())openTask('pingpong');else $('#pingCount').focus()};
const originalOpenTask=openTask,originalDrawStimulus=drawStimulus,originalAnswer=answer,originalRenderResult=renderResult;
openTask=function(type){clearTimeout(state.timer);stopRadar();setAnswers(false);originalOpenTask(type);const ping=isPing(type),receiver=type==='receiver',n=ping?(receiver?receiverN:pingN):20;state.plannedCount=n;state.trialDifficulty=state.difficulty;$('#pingInstructions').classList.toggle('hidden',!ping);$('#instructionCount').textContent=n;$('#instructionDuration').textContent=ping?'3.6s':'1.2s';$('#trialCounter').textContent=`01 / ${n}`;const definitions={radar:'信号：扫描时出现异常目标；噪声：只有背景与干扰亮点。',medical:'信号：存在可疑病灶；噪声：正常组织、纹理和正常亮斑。',texture:'信号：存在明显偏转线条；噪声：规则纹理及轻微扰动。',pingpong:'信号：发球存在违规；噪声：发球合规。H = 违规且判违规，M = 违规却判合规，FA = 合规却判违规，CR = 合规且判合规。'};$('#scenarioDefinition').textContent=(definitions[type]||definitions.pingpong)+` 本局 ${n} 次，信号 ${Math.floor(n/2)} 次，噪声 ${n-Math.floor(n/2)} 次；P(S) = ${Math.floor(n/2)}/${n}，随机排列。本局统一清晰度 ${state.trialDifficulty.toFixed(1)}。`;$('#answerPresent strong').textContent=ping?'发球违规':'出现信号';$('#answerAbsent strong').textContent=ping?'发球合规':'未出现信号';$('#answerPresent small').textContent=ping?'至少一项动作不符合指导语':'画面中有异常目标';$('#answerAbsent small').textContent=ping?'动作均符合指导语':'画面中没有异常'};
startExperiment=function(){state.index=0;state.answers=[];const ping=isPing(state.currentTask),n=ping?state.plannedCount:20,types=state.currentTask==='receiver'?['occlusion','backtoss']:PING_TYPES;state.trials=shuffleTrials(Array.from({length:n},(_,i)=>({signal:i<Math.floor(n/2),seed:Math.random(),kind:types[(i<Math.floor(n/2)?i:i-Math.floor(n/2))%types.length]})));$('#instructionPanel').classList.add('hidden');$('#trialPanel').classList.remove('hidden');nextTrial()};
$('#startTrials').onclick=()=>startExperiment();
nextTrial=function(){if(state.index>=state.trials.length)return finishExperiment();const tr=state.trials[state.index],ping=isPing(state.currentTask),duration=ping?PING_DURATION:1200;$('#trialCounter').textContent=`${String(state.index+1).padStart(2,'0')} / ${state.trials.length}`;$('#trialProgress').style.width=`${state.index/state.trials.length*100}%`;$('#maskLayer').classList.add('hidden');setAnswers(false);setFeedback('neutral','·','仔细观察',`刺激将在 ${duration/1000} 秒后隐藏`);drawStimulus(state.currentTask,tr.signal,tr.seed,state.trialDifficulty);state.timer=setTimeout(()=>{stopRadar();$('#maskLayer').classList.remove('hidden');setAnswers(true);state.shownAt=performance.now();setFeedback('neutral','?','请作答',ping?'F：发球违规；J：发球合规':'选择“出现信号”或“未出现信号”')},duration)};
answer=function(present){if(!views.task.classList.contains('active')||$('#trialPanel').classList.contains('hidden')||state.index>=state.trials.length||$('#answerPresent').disabled)return;const ping=isPing(state.currentTask),tr=state.trials[state.index];originalAnswer(present);if(ping){const a=state.answers.at(-1);a.kind=tr.kind;a.seed=tr.seed;a.details=state.currentTask==='receiver'?receiverSpec(tr,state.trialDifficulty):pingSpec(tr,state.trialDifficulty);const labels={H:'命中：违规，判为违规',M:'漏报：违规，判为合规',FA:'虚报：合规，判为违规',CR:'正确驳斥：合规，判为合规'};setFeedback(['H','CR'].includes(a.outcome)?'correct':'wrong',['H','CR'].includes(a.outcome)?'✓':'×',labels[a.outcome],state.currentTask==='receiver'?receiverExplanation(a.details):pingExplanation(a.details));clearTimeout(state.timer);state.timer=setTimeout(nextTrial,2200)}};
function pingSpec(tr,d){const random=mulberry32(Math.floor(tr.seed*1e9)),q=(d-.5)/3,m=.6+q*7+random()*.3,bad=tr.signal,k=tr.kind;return{kind:k,bad,height:k==='height'?16+(bad?-1:1)*m:24+random()*4,angle:k==='angle'?30+(bad?1:-1)*(2+q*20):5+random()*4,pinched:k==='palm'&&bad,position:k==='position'?(bad?1:-1)*(2+q*28):-28,covered:k==='occlusion'&&bad,landing:k==='doubles'?(bad?-1:1)*(.025+q*.28):.28,skipOwn:k==='sequence'&&bad,out:k==='out'&&bad,q}}
function pingExplanation(s){const facts={height:`抛球高度 ${s.height.toFixed(1)} cm；要求至少16 cm。`,angle:`抛球夹角 ${s.angle.toFixed(1)}°；本任务阈值30°。`,palm:s.pinched?'起始持球用手指夹球，手掌未平伸。':'起始球静止置于张开的平伸手掌。',position:`击球位置在端线${s.position>0?'前':'后'} ${Math.abs(s.position).toFixed(1)} cm，球高于台面。`,occlusion:s.covered?'击球瞬间，前臂挡住球与球拍。':'击球瞬间，球与球拍可见。',doubles:s.landing<0?'双打：对方落点位于错误半区。':'双打：从本方右半台发往对方右半台。',sequence:s.skipOwn?'球直接到对方台区，未先触本方台区。':'球先触本方台区，再落入对方台区。',out:s.out?'球越过球网后直接出界，未落在对方台区。':'球先触本方，再越网落入对方台区。'};return facts[s.kind]}
drawStimulus=function(type,signal,seed,d){if(!isPing(type))return originalDrawStimulus(type,signal,seed,d);stopRadar();const s=type==='receiver'?receiverSpec(state.trials[state.index],d):pingSpec(state.trials[state.index],d),canvas=$('#stimulusCanvas'),ctx=canvas.getContext('2d'),started=performance.now();function frame(now){(type==='receiver'?drawReceiverFrame:drawPingFrame)(ctx,s,Math.min(1,(now-started)/PING_DURATION));if(now-started<PING_DURATION)state.radarFrame=requestAnimationFrame(frame);else state.radarFrame=null}frame(started)};
function drawPingFrame(c,s,t){
  c.clearRect(0,0,760,420);c.fillStyle='#eaf1ef';c.fillRect(0,0,760,420);
  const text=(str,x,y,size=15)=>{c.fillStyle='#244a50';c.font=`${size}px sans-serif`;c.fillText(str,x,y)},line=(x1,y1,x2,y2,color='#315c66',width=2)=>{c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke()},ball=(x,y)=>{c.fillStyle='#fff';c.strokeStyle='#e39534';c.lineWidth=2;c.beginPath();c.arc(x,y,6,0,Math.PI*2);c.fill();c.stroke()};
  text('侧视 · 端线 / 台面 / 抛球轨迹',22,26);text(s.kind==='doubles'?'双打 · 右半台 → 右半台':'单打 · 发球动作',500,26);
  c.fillStyle='#17697a';c.fillRect(160,238,290,13);line(305,195,305,238,'#667e81',4);for(let y=199;y<237;y+=8)line(295,y,315,y,'#879b9b',1);line(160,252,160,316);line(450,252,450,316);text('本方',210,276);text('对方',365,276);text('端线',148,336,12);text('球网',289,186,12);
  // Player and open palm; the ball starts stationary for the first .10 of a clip.
  c.fillStyle='#e6a179';c.beginPath();c.arc(70,144,18,0,7);c.fill();line(70,166,74,230,'#244a50',25);line(72,230,48,298,'#244a50',12);line(80,230,102,298,'#244a50',12);line(79,184,115,210,'#e6a179',12);line(115,210,142,210,'#e6a179',8);
  const hitX=160+s.position*1.25,hitY=214,releaseX=hitX,releaseY=210,peakY=releaseY-s.height*2.8,peakX=releaseX+Math.tan(s.angle*Math.PI/180)*s.height*2.8;
  line(releaseX,releaseY,releaseX,peakY,'#a8b9ba',1);c.setLineDash([4,4]);line(releaseX,releaseY,peakX,peakY,'#6c9298',1);c.setLineDash([]);line(146,releaseY,146,releaseY-16*2.8,'#c69b44',2);text('16cm',102,164,12);
  let bx=releaseX,by=releaseY;const u=(t-.1)/.34;if(t>=.1&&t<.44){const f=Math.sin(Math.PI*Math.max(0,u));bx=releaseX+(peakX-releaseX)*f;by=releaseY-(releaseY-peakY)*f}
  if(t>=.44){const f=Math.min(1,(t-.44)/.48),own=[232,232],other=[390,232],nodes=s.skipOwn?[[hitX,hitY],[305,188],other,[445,190]]:s.out?[[hitX,hitY],own,[305,188],[470,210],[483,305]]:[[hitX,hitY],own,[305,188],other,[445,190]],v=f*(nodes.length-1),i=Math.min(nodes.length-2,Math.floor(v)),r=v-i;bx=nodes[i][0]+(nodes[i+1][0]-nodes[i][0])*r;by=nodes[i][1]+(nodes[i+1][1]-nodes[i][1])*r-20*Math.sin(Math.PI*r);}
  if(t>.37&&t<.53){c.fillStyle='#d46b45';c.beginPath();c.ellipse(hitX-10,hitY+1,10,16,-.5,0,7);c.fill();line(hitX-17,hitY+11,hitX-24,hitY+22,'#875e3e',5)}ball(bx,by);
  if(s.covered&&t>.37&&t<.54){line(hitX-18,hitY-13,hitX+20,hitY+10,'#e6a179',24)}
  // Magnified local detail is identical for signal/noise apart from the relevant fact.
  c.fillStyle='#fff';c.fillRect(22,354,350,52);text('动作局部',30,373,12);
  if(s.kind==='palm'){text('起始持球（放大）',110,373,12);line(220,390,286,390,'#e6a179',9);ball(255,380);if(s.pinched){line(241,393,252,376,'#e6a179',6);line(271,393,261,374,'#e6a179',6)}else{for(let i=0;i<4;i++)line(271,385+i*4,290,385+i*4,'#e6a179',2)}}
  else if(s.kind==='height')text(`抛球峰值 ${s.height.toFixed(1)} cm`,115,387,17);
  else if(s.kind==='angle')text(`上升夹角 ${s.angle.toFixed(1)}°`,115,387,17);
  else if(s.kind==='position')text(`击球点 · 端线${s.position>0?'前':'后'} ${Math.abs(s.position).toFixed(1)} cm`,110,387,15);
  else if(s.kind==='occlusion'){text('击球瞬间（放大）',108,373,12);c.fillStyle='#d46b45';c.fillRect(238,379,16,22);ball(257,388);if(s.covered)line(228,380,276,398,'#e6a179',22)}
  else text('观察球的落台顺序和最终落点',103,387,14);
  // Top view: server's right is screen-bottom; receiver's right is screen-top.
  const tx=493,ty=92,tw=240,th=132;c.fillStyle='#17697a';c.fillRect(tx,ty,tw,th);line(tx+tw/2,ty,tx+tw/2,ty+th,'#fff',2);line(tx,ty+th/2,tx+tw,ty+th/2,'#e3eff0',1);text('落点俯视 · 本方 → 对方',494,71,13);text('本方右半台',492,246,12);text('对方右半台',638,84,12);
  if(t>.52&&!s.skipOwn){ball(tx+tw*.25,ty+th*.76);text('①',tx+tw*.25-16,ty+th*.76-12,12)}
  if(t>.77){const lx=s.out?tx+tw+12:tx+tw*.77,ly=s.kind==='doubles'?ty+th*(.5-s.landing):ty+th*.26;ball(lx,ly);text(s.skipOwn?'①':'②',lx-16,ly-12,12)}
  text(t<.1?'准备持球':t<.44?'向上抛球':t<.53?'击球瞬间':'飞行与落台',493,306,18);
  c.fillStyle='#c8f26b';c.fillRect(493,327,240*t,4);
}
finishExperiment=function(){$('#trialProgress').style.width='100%';setAnswers(false);state.result=calcResult();const r=state.result,record={time:new Date().toISOString(),name:state.user?.name||'游客',studentId:state.user?.id||'游客',task:state.currentTask,taskName:TASKS[state.currentTask].label,setD:state.trialDifficulty,trialCount:state.trials.length,prior:state.trials.filter(t=>t.signal).length/state.trials.length,answers:state.answers,...r};const all=getRecords();all.push(record);localStorage.setItem(STORAGE,JSON.stringify(all));renderResult();showView('result')};
renderResult=function(){originalRenderResult();if(isPing(state.currentTask)){const r=state.result;$('#confusionMatrix').innerHTML=`<div></div><div class="head">判违规</div><div class="head">判合规</div><div class="head">实际违规</div><div class="hit"><small>命中 H</small><strong>${r.H}</strong></div><div class="miss"><small>漏报 M</small><strong>${r.M}</strong></div><div class="head">实际合规</div><div class="fa"><small>虚报 FA</small><strong>${r.FA}</strong></div><div class="cr"><small>正确驳斥 CR</small><strong>${r.CR}</strong></div>`;$('#resultSummary').textContent+=` 本局 ${state.trials.length} 次；难度设置 ${state.trialDifficulty.toFixed(1)}，实测 d′ ${r.dp.toFixed(2)}。`}};
$('#taskFilter').insertAdjacentHTML('beforeend','<option value="pingpong">乒乓球发球</option>');
